game_title = 'Build and steal time'
local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()
local Window = Rayfield:CreateWindow({
   Name = game_title,
   Icon = 0, -- Icon in Topbar. Can use Lucide Icons (string) or Roblox Image (number). 0 to use no icon (default).
   LoadingTitle = "Loading",
   LoadingSubtitle = "by Rico19374 ( @fredricokenzie YT )",
   ShowText = "Rayfield", -- for mobile users to unhide rayfield, change if you'd like
   Theme = "Serenity", -- Check https://docs.sirius.menu/rayfield/configuration/themes

   ToggleUIKeybind = "K", -- The keybind to toggle the UI visibility (string like "K" or Enum.KeyCode)

   DisableRayfieldPrompts = false,
   DisableBuildWarnings = false, -- Prevents Rayfield from warning when the script has a version mismatch with the interface

   ConfigurationSaving = {
      Enabled = true,
      FolderName = nil, -- Create a custom folder for your hub/game
      FileName = "Big Hub"
   },

   Discord = {
      Enabled = false, -- Prompt the user to join your Discord server if their executor supports it
      Invite = "noinvitelink", -- The Discord invite code, do not include discord.gg/. E.g. discord.gg/ ABCD would be ABCD
      RememberJoins = true -- Set this to false to make them join the discord every time they load it up
   },

   KeySystem = true, -- Set this to true to use our key system
   KeySettings = {
      Title = "1 step verification",
      Subtitle = "idk",
      Note = "type 1234", -- Use this to tell the user how to get a key
      FileName = "Key", -- It is recommended to use something unique as other scripts using Rayfield may overwrite your key file
      SaveKey = false, -- The user's key will be saved, but if you change the key, they will be unable to use your script
      GrabKeyFromSite = false, -- If this is true, set Key below to the RAW site you would like Rayfield to get the key from
      Key = {"1234"} -- List of keys that will be accepted by the system, can be RAW file links (pastebin, github etc) or simple strings ("hello","key22")
   }
})
local set_time = 0
local Tab = Window:CreateTab("Time", 4483362458) -- Title, Image
local Input = Tab:CreateInput({
   Name = "Set time",
   CurrentValue = "",
   PlaceholderText = "Max is 64 bit integer limit",
   RemoveTextAfterFocusLost = false,
   Flag = "Input1",
   Callback = function(Text)
    set_time = tonumber(Text)
   end,
})
local Button = Tab:CreateButton({
   Name = "Set time",
   Callback = function()
    local args = {set_time-(set_time*2), "deposite"}
    game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui"):WaitForChild("bank"):WaitForChild("RemoteEvent"):FireServer(unpack(args))
   end,
})
local Button2 = Tab:CreateButton({
   Name = "Set time to 64 bit integer limit ( click twice for negative time )",
   Callback = function()
    local args = {-9223372036854770000, "deposite"}
    game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui"):WaitForChild("bank"):WaitForChild("RemoteEvent"):FireServer(unpack(args))
   end,
})
local Button4 = Tab:CreateButton({
   Name = "Store all time",
   Callback = function()
    local args = {game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui"):WaitForChild("leaderstats").Time.Value,"deposite"}
    game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui"):WaitForChild("bank"):WaitForChild("RemoteEvent"):FireServer(unpack(args))
   end,
})

local Label = Tab:CreateLabel("UR SAVED TIME MAY GOT DECREASED FOR TIME", 4483362458, Color3.fromRGB(255, 255, 255), false) -- Title, Icon, Color, IgnoreTheme
local Tab2 = Window:CreateTab("Extras", 4483362458)
local Button3 = Tab2:CreateButton({
   Name = "Infinite yield",
   Callback = function()
    loadstring(game:HttpGet('https://raw.githubusercontent.com/EdgeIY/infiniteyield/master/source'))()
   end,
})
